"""Install explicit HTTP action receipts without changing request authorization."""
import base64,fcntl,hashlib,os,subprocess,tempfile,time
from pathlib import Path
MANIFEST = {'automation/server/phone_ui.py': {'data': '', 'sha256': 'dd0d06479d3a3aba2e18620491fd2464ccdefe2cffc74f95f9d46f786db290f8', 'previous': '12f1dea3161f3598ed55e9ebeaa7920710fd0c20de66b9bec66deb55c3bdcd81'}, 'automation/server/phone_view.py': {'data': '', 'sha256': 'ebb01f8a98e6249750a548af341ff11bca562e9159781c6922a3341b68b7b7b7', 'previous': 'f5181958cb1a985ff0c4c4604b3acb7eecc7f8e81febca0153187e8050b5c39e'}, 'automation/server/test_phone_view.py': {'data': '', 'sha256': '9094c1e52c1196dc87069d3d20ebf7c27907859919328614e9d767335f4ef80b', 'previous': '033431b3911b3cf8763f86c6d101c74f7e10e5482dc775bb3065895e27e6b467'}}

def replace(path,raw,meta):
    fd,name=tempfile.mkstemp(dir=path.parent,prefix='.phone-receipt-')
    try:
        with os.fdopen(fd,'wb') as stream:
            stream.write(raw);stream.flush();os.fsync(stream.fileno())
            os.fchown(stream.fileno(),meta.st_uid,meta.st_gid)
            os.fchmod(stream.fileno(),meta.st_mode&0o7777)
        os.replace(name,path)
    finally:Path(name).unlink(missing_ok=True)

def prepare(root):
    plans=[]
    for name,item in MANIFEST.items():
        target=root/name
        if target.is_symlink() or not target.is_file():raise RuntimeError('Unknown installed file')
        before=target.read_bytes();raw=base64.b64decode(item['data'],validate=True)
        if hashlib.sha256(raw).hexdigest()!=item['sha256']:raise RuntimeError('Invalid setup payload')
        if hashlib.sha256(before).hexdigest() not in {item['previous'],item['sha256']}:
            raise RuntimeError('Unknown installed version; no files changed')
        compile(raw,str(target),'exec')
        plans.append((target,raw,before,target.stat()))
    return plans

def main():
    if os.geteuid()!=0:raise RuntimeError('Root required')
    root=Path('/opt/fh6/repo');store=Path('/var/lib/fh6')
    if (store/'runner.lock').is_symlink():raise RuntimeError('Unexpected lock')
    with (store/'runner.lock').open('rb') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        plans=prepare(root)
        if subprocess.run(['systemctl','is-active','--quiet','fh6-phone.service']).returncode:
            raise RuntimeError('Phone service must already be active')
        backup=store/'repairs'/('phone-action-receipts-'+str(time.time_ns()))
        backup.mkdir(mode=0o700,parents=True)
        for index,(_,_,before,_) in enumerate(plans):
            saved=backup/str(index);saved.write_bytes(before);saved.chmod(0o600)
        applied=[]
        try:
            subprocess.run(['systemctl','stop','fh6-phone.service'],check=True,timeout=30)
            for target,raw,before,meta in plans:
                replace(target,raw,meta);applied.append((target,before,meta))
            subprocess.run(['/usr/bin/python3','-m','unittest','test_phone_view','test_server'],
                           cwd=root/'automation/server',check=True,timeout=90)
            subprocess.run(['systemctl','start','fh6-phone.service'],check=True,timeout=30)
            subprocess.run(['systemctl','is-active','--quiet','fh6-phone.service'],check=True,timeout=10)
        except BaseException:
            for target,before,meta in reversed(applied):replace(target,before,meta)
            subprocess.run(['systemctl','start','fh6-phone.service'],timeout=30)
            raise
    print('PHONE_ACTION_RECEIPTS_INSTALLED same-origin protection retained; no real task or Steam publication requested')
    print('BACKUP='+str(backup))

if __name__=='__main__':
    try:main()
    except Exception as error:
        print('PHONE_ACTION_RECEIPTS_FAILED type='+type(error).__name__)
        raise SystemExit(1)
